import React, {
  useRef,
  useMemo,
  useEffect,
  type ReactNode,
  Suspense,
} from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import type { Theme } from '../types';

// ─── Live theme ref shared across R3F ─────────────────────
// We use a mutable ref so Three objects update every frame
// without triggering React re-renders inside the canvas.
export const themeRef = { current: {} as Theme };

// ─── Particles ────────────────────────────────────────────
function Particles(): JSX.Element {
  const groupRef = useRef<THREE.Points>(null!);
  const matRef = useRef<THREE.PointsMaterial>(null!);

  const count = 1600;
  const positions = useMemo<Float32Array>(() => {
    const arr = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      arr[i * 3] = (Math.random() - 0.5) * 22;
      arr[i * 3 + 1] = (Math.random() - 0.5) * 22;
      arr[i * 3 + 2] = (Math.random() - 0.5) * 12;
    }
    return arr;
  }, []);

  useFrame(({ clock }) => {
    groupRef.current.rotation.y = clock.elapsedTime * 0.04;
    groupRef.current.rotation.x = clock.elapsedTime * 0.015;
    if (matRef.current) {
      const th = themeRef.current;
      matRef.current.color.setHex(th.particleHex);
      matRef.current.opacity = th.particleOpacity;
    }
  });

  return (
    <points ref={groupRef}>
      <bufferGeometry>
        <bufferAttribute attach='attributes-position' args={[positions, 3]} />
      </bufferGeometry>
      <pointsMaterial
        ref={matRef}
        color={0x8b6fff}
        size={0.025}
        sizeAttenuation
        transparent
        opacity={0.55}
      />
    </points>
  );
}

// ─── Floating wireframe shape ─────────────────────────────
interface ShapeProps {
  geometry: ReactNode;
  position: [number, number, number];
  rotSpeed: [number, number, number]; // [rx, ry, phaseOffset]
}

function FloatingShape({
  geometry,
  position,
  rotSpeed,
}: ShapeProps): JSX.Element {
  const meshRef = useRef<THREE.Mesh>(null!);
  const matRef = useRef<THREE.MeshBasicMaterial>(null!);

  useFrame(({ clock }) => {
    meshRef.current.rotation.x += rotSpeed[0];
    meshRef.current.rotation.y += rotSpeed[1];
    meshRef.current.position.y =
      position[1] + Math.sin(clock.elapsedTime * 0.5 + rotSpeed[2]) * 0.18;
    if (matRef.current) {
      const th = themeRef.current;
      matRef.current.color.setHex(th.particleHex);
      matRef.current.opacity = th.wireOpacity;
    }
  });

  return (
    <mesh ref={meshRef} position={position}>
      {geometry}
      <meshBasicMaterial
        ref={matRef}
        color={0x8b6fff}
        wireframe
        transparent
        opacity={0.09}
      />
    </mesh>
  );
}

// ─── Camera parallax ──────────────────────────────────────
function CameraRig(): null {
  const { camera } = useThree();
  const mouse = useRef<[number, number]>([0, 0]);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      mouse.current = [
        e.clientX / window.innerWidth - 0.5,
        e.clientY / window.innerHeight - 0.5,
      ];
    };
    window.addEventListener('mousemove', handler);
    return () => window.removeEventListener('mousemove', handler);
  }, []);

  useFrame(() => {
    camera.position.x += (mouse.current[0] * 0.6 - camera.position.x) * 0.03;
    camera.position.y += (-mouse.current[1] * 0.3 - camera.position.y) * 0.03;
  });

  return null;
}

// ─── Scene ────────────────────────────────────────────────
function SceneContent(): JSX.Element {
  const shapes: ShapeProps[] = useMemo(
    () => [
      {
        geometry: <octahedronGeometry args={[0.6, 0]} />,
        position: [-3.5, 1.5, -1],
        rotSpeed: [-0.003, 0.005, 0.3],
      },
      {
        geometry: <tetrahedronGeometry args={[0.5, 0]} />,
        position: [3.2, -1.2, -0.5],
        rotSpeed: [0.004, -0.006, 1.7],
      },
      {
        geometry: <icosahedronGeometry args={[0.45, 0]} />,
        position: [-2.8, -2, -2],
        rotSpeed: [-0.005, 0.003, 3.1],
      },
      {
        geometry: <octahedronGeometry args={[0.35, 0]} />,
        position: [3.8, 2.2, -1.5],
        rotSpeed: [0.002, -0.007, 5.0],
      },
    ],
    [],
  );

  return (
    <>
      <CameraRig />
      <Particles />
      {shapes.map((s, i) => (
        <FloatingShape key={i} {...s} />
      ))}
    </>
  );
}

// ─── Public canvas wrapper ────────────────────────────────
export function ThreeCanvas(): JSX.Element {
  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 0,
        pointerEvents: 'none',
      }}
    >
      <Canvas
        camera={{ position: [0, 0, 5], fov: 60 }}
        gl={{ alpha: true, antialias: true }}
      >
        <Suspense fallback={null}>
          <SceneContent />
        </Suspense>
      </Canvas>
    </div>
  );
}
